```javascript
const express = require("express");
const axios = require("axios");
const https = require("node:https");
const { createHash } = require("node:crypto");
const Redis = require("ioredis");

const app = express();
app.use(express.json({ limit: "32kb" }));

const redis = new Redis({
  host: process.env.REDIS_HOST || "redis",
  port: 6379,
  enableOfflineQueue: false,
  maxRetriesPerRequest: 1,
  commandTimeout: 50, // Illustrative cache budget; tune from measurements.
});
redis.on("error", err => console.error("Redis:", err.message));

const deepl = axios.create({
  baseURL: process.env.DEEPL_BASE_URL || "https://api.deepl.com",
  headers: {
    Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
  },
  httpsAgent: new https.Agent({ keepAlive: true, maxSockets: 50 }),
  timeout: 1000, // Illustrative provider timeout, not a 200 ms guarantee.
});

const inFlight = new Map();

async function translateText(text, targetLang, sourceLang) {
  const hash = createHash("sha256")
    .update(JSON.stringify([text, sourceLang || null, targetLang]))
    .digest("hex");
  const key = `translation:v1:${hash}`;

  try {
    const cached = await redis.get(key);
    if (cached !== null) {
      return { translatedText: cached, cached: true };
    }
  } catch {
    // A cache outage must not prevent direct translation.
  }

  // Coalesce simultaneous identical cache misses within this process.
  if (inFlight.has(key)) return inFlight.get(key);

  const task = (async () => {
    const { data } = await deepl.post("/v2/translate", {
      text: [text],
      target_lang: targetLang,
      ...(sourceLang ? { source_lang: sourceLang } : {}),
    });

    const translatedText = data.translations[0].text;

    // Do not delay delivery while waiting for a cache write.
    void redis.set(key, translatedText, "EX", 900)
      .catch(err => console.error("Cache write:", err.message));

    return { translatedText, cached: false };
  })();

  inFlight.set(key, task);
  try {
    return await task;
  } finally {
    inFlight.delete(key);
  }
}

app.post("/api/translate", async (req, res) => {
  const { text, targetLang, sourceLang } = req.body;

  if (
    typeof text !== "string" || !text.trim() ||
    typeof targetLang !== "string" || !targetLang.trim() ||
    (sourceLang !== undefined && typeof sourceLang !== "string")
  ) {
    return res.status(400).json({ error: "Invalid translation input" });
  }

  try {
    const result = await translateText(
      text,
      targetLang.trim().toUpperCase(),
      sourceLang?.trim().toUpperCase()
    );
    return res.json({ ...result, fallback: false });
  } catch (err) {
    console.error("Translation failed:", err.response?.status || err.code);

    // Explicit degraded response—not a successful translation.
    return res.json({
      translatedText: text,
      cached: false,
      fallback: true,
      error: "Translation temporarily unavailable",
    });
  }
});

app.listen(4500);
```

