### Recommended implementation

Use a reusable Axios client, keep-alive connections, proper `await`/error handling, and Redis caching. Here is an illustrative implementation using your existing stack:

```javascript
const express = require('express');
const axios = require('axios');
const https = require('node:https');
const { createHash } = require('node:crypto');
const Redis = require('ioredis');

const app = express();
app.use(express.json({ limit: '64kb' }));

const redis = new Redis({
  host: process.env.REDIS_HOST || 'redis',
  port: 6379,
  connectTimeout: 100,
  commandTimeout: 50,
  maxRetriesPerRequest: 0,
  enableOfflineQueue: false,
});

redis.on('error', err => console.error('Redis:', err.message));

const deepl = axios.create({
  baseURL: 'https://api.deepl.com/v2',
  headers: {
    Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
  },
  httpsAgent: new https.Agent({ keepAlive: true }),
  timeout: 250, // Illustrative: tune against measured latency and your SLA.
});

const inFlight = new Map();
const cacheStats = { hits: 0, misses: 0, errors: 0 };

async function translateText(text, targetLang, sourceLang) {
  // Include every translation-affecting option in the key.
  const key = 'translation:' + createHash('sha256')
    .update(JSON.stringify([text, sourceLang || null, targetLang]))
    .digest('hex');

  try {
    const cached = await redis.get(key);
    if (cached !== null) {
      cacheStats.hits++;
      return { translatedText: cached, cached: true, fallback: false };
    }
    cacheStats.misses++;
  } catch {
    cacheStats.errors++;
    // Redis failure must not prevent a direct provider call.
  }

  // Merge identical concurrent misses within this service instance.
  if (inFlight.has(key)) return inFlight.get(key);

  const pending = (async () => {
    const body = { text: [text], target_lang: targetLang };
    if (sourceLang) body.source_lang = sourceLang;

    const response = await deepl.post('/translate', body);
    const translatedText = response.data.translations[0].text;

    // Do not hold up the response while writing the cache.
    void redis.set(key, translatedText, 'EX', 900)
      .catch(() => { cacheStats.errors++; });

    return { translatedText, cached: false, fallback: false };
  })();

  inFlight.set(key, pending);
  try {
    return await pending;
  } finally {
    inFlight.delete(key);
  }
}

app.post('/api/translate', async (req, res) => {
  const { text, targetLang, sourceLang } = req.body;

  if (
    typeof text !== 'string' || !text.trim() ||
    typeof targetLang !== 'string' || !targetLang.trim() ||
    (sourceLang !== undefined && typeof sourceLang !== 'string')
  ) {
    return res.status(400).json({ error: 'Invalid translation input' });
  }

  try {
    const result = await translateText(
      text,
      targetLang.toUpperCase(),
      sourceLang?.toUpperCase()
    );
    return res.json(result);
  } catch (err) {
    console.error('Translation failed:', {
      status: err.response?.status,
      code: err.code,
    });

    // Preserve chatbot responsiveness without pretending translation succeeded.
    return res.json({
      translatedText: text,
      cached: false,
      fallback: true,
      reason: 'translation_unavailable',
    });
  }
});

app.listen(4500);
```

